definitions/artifacts/functions/claim-re.content:
{
    "type": "function",
    "function": {
        "id": "recordMondialRelayClaimReturnCarrierAcceptance",
        "method": "POST",
        "access": {
            "mode": "system"
        },
        "meta": {
            "name": "Record claim return carrier acceptance",
            "description": "Refresh a claim-bound Mondial Relay return and project only trusted carrier acceptance into Commerce."
        },
        "input": {
            "body": {
                "type": "object",
                "properties": {
                    "claimId": {
                        "type": "number"
                    },
                    "expeditionNumber": {
                        "type": "string"
                    }
                },
                "required": [
                    "claimId",
                    "expeditionNumber"
                ]
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "id": "deliveryContext",
                "call": {
                    "source": "{{dependencies.delivery.sourceId}}",
                    "endpoint": "shipmentTrackingContext",
                    "params": {
                        "expeditionNumber": "$input.body.expeditionNumber",
                        "expectedExternalOrderId": {
                            "$concat": [
                                "claim-return:",
                                "$input.body.claimId"
                            ]
                        }
                    }
                }
            },
            {
                "assert": {
                    "condition": {
                        "equals": [
                            "$steps.deliveryContext.shipment.externalOrderId",
                            {
                                "$concat": [
                                    "claim-return:",
                                    "$input.body.claimId"
                                ]
                            }
                        ]
                    },
                    "failure": {
                        "status": 409,
                        "error": "Shipment is not bound to this marketplace claim return"
                    }
                }
            },
            {
                "assert": {
                    "condition": {
                        "notEquals": [
                            "$steps.deliveryContext.tracking.carrierAcceptedAt",
                            null
                        ]
                    },
                    "failure": {
                        "status": 409,
                        "error": "Return has no trusted carrier acceptance yet"
                    }
                }
            },
            {
                "id": "commerceClaim",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "recordClaimReturnDelivery",
                    "body": {
                        "claimId": "$input.body.claimId",
                        "providerEventId": {
                            "$concat": [
                                "mondial-relay-return|",
                                "$input.body.expeditionNumber",
                                "|carrier_accepted|",
                                "$steps.deliveryContext.tracking.carrierAcceptedAt"
                            ]
                        },
                        "providerReference": "$input.body.expeditionNumber",
                        "normalizedStatus": "carrier_accepted",
                        "occurredAt": "$steps.deliveryContext.tracking.carrierAcceptedAt",
                        "providerEvidence": {
                            "provider": "mondial-relay",
                            "shipmentId": "$steps.deliveryContext.shipment.id",
                            "providerStatus": "$steps.deliveryContext.tracking.status"
                        }
                    }
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "shipment": "$steps.deliveryContext.shipment",
                "tracking": "$steps.deliveryContext.tracking",
                "claim": "$steps.commerceClaim"
            }
        }
    }
}

{
    "id": "createClaimReturnShipmentForMyPurchase",
    "method": "POST",
    "access": {
        "mode": "auth"
    },
    "meta": {
        "name": "Create claim return shipment for my purchase",
        "description": "Create one idempotent buyer-to-seller claim return from trusted Commerce and account snapshots."
    },
    "input": {
        "body": {
            "type": "object",
            "properties": {
                "claimId": {
                    "type": "number"
                }
            },
            "required": [
                "claimId"
            ]
        }
    },
    "output": [
        {
            "status": "200",
            "body": {
                "type": "object"
            }
        }
    ],
    "steps": {
        "$include": "steps/root.json"
    },
    "return": {
        "status": 200,
        "body": {
            "claimId": "$steps.authorization.claimId",
            "shipment": {
                "id": "$steps.shipment.id",
                "expeditionNumber": "$steps.shipment.expeditionNumber",
                "trackingUrl": "$steps.shipment.trackingUrl",
                "status": "$steps.shipment.status",
