{
    "type": "function",
    "function": {
        "id": "publishMondialRelayDeliveryHealth",
        "method": "POST",
        "access": {
            "mode": "system"
        },
        "meta": {
            "name": "Publish Mondial Relay Delivery health",
            "description": "Publish a global worker heartbeat and isolated order shipment watermarks without freezing unrelated settlements."
        },
        "input": {
            "body": {
                "type": "object",
                "properties": {
                    "runKey": {
                        "type": "string"
                    },
                    "limit": {
                        "type": "number"
                    }
                },
                "required": [
                    "runKey",
                    "limit"
                ]
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "id": "projectionHealth",
                "call": {
                    "source": "{{dependencies.delivery.sourceId}}",
                    "endpoint": "deliveryProjectionHealth"
                }
            },
            {
                "id": "globalHealth",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "recordDeliveryReconciliationHealth",
                    "body": {
                        "runKey": "$input.body.runKey",
                        "checkedAt": "$steps.projectionHealth.checkedAt",
                        "pendingProjectionCount": "$steps.projectionHealth.pendingProjectionCount",
                        "manualReviewCount": "$steps.projectionHealth.manualReviewCount",
                        "trackingErrorCount": "$steps.projectionHealth.trackingErrorCount"
                    }
                }
            },
            {
                "id": "orders",
                "forEach": {
                    "items": "$steps.projectionHealth.orders",
                    "max": 24,
                    "steps": [
                        {
                            "id": "orderHealth",
                            "call": {
                                "source": "{{dependencies.commerce.sourceId}}",
                                "endpoint": "recordDeliveryOrderReconciliationHealth",
                                "body": {
                                    "runKey": "$input.body.runKey",
                                    "checkedAt": "$steps.projectionHealth.checkedAt",
                                    "orderPublicId": "$item.externalOrderId",
                                    "shipmentId": "$item.shipmentId",
                                    "providerReference": "$item.providerReference",
                                    "shipmentStatus": "$item.shipmentStatus",
                                    "pendingProjectionCount": "$item.pendingProjectionCount",
                                    "manualReviewCount": "$item.manualReviewCount",
                                    "trackingErrorCount": "$item.trackingErrorCount",
                                    "trackingCheckedAt": "$item.trackingCheckedAt"
                                }
                            }
                        }
                    ],
                    "yield": "$steps.orderHealth"
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "global": "$steps.globalHealth",
                "orders": "$steps.orders"
            }
        }
    }
}

{
    "id": "reconcileMondialRelayFulfillments",
    "method": "POST",
    "access": {
        "mode": "system"
    },
    "meta": {
        "name": "Reconcile Mondial Relay fulfillments",
        "description": "Synchronize a bounded provider batch and project normalized events into Commerce."
    },
    "input": {
        "body": {
            "type": "object",
            "properties": {
                "runKey": {
                    "type": "string"
                },
                "limit": {
                    "type": "number"
                }
            },
            "required": [
                "runKey",
                "limit"
            ]
        }
    },
    "output": [
        {
            "status": "200",
            "body": {
                "type": "object"
            }
        }
    ],
    "steps": {
        "$include": "steps.json"
    },
    "return": {
        "status": 200,
        "body": {
            "processed": "$steps.deliveryBatch.processed",
            "shipments": "$steps.deliveryBatch.shipments",
            "events": "$steps.commerceEvents",
            "claimReturnEvents": "$steps.commerceClaimReturnEvents"
        }
    }
}

[
    {
        "id": "deliveryBatch",
        "call": {
            "source": "{{dependencies.delivery.sourceId}}",
            "endpoint": "reconcileShipments",
            "body": {
                "runKey": "$input.body.runKey",
                "limit": 8
            }
        }
    },
    {
        "id": "commerceEvents",
        "forEach": {
            "items": "$steps.deliveryBatch.events",
            "max": 8,
            "continueOnError": true,
            "steps": [
                {
                    "id": "record",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "recordOrderFulfillment",
                        "body": {
                            "orderPublicId": "$item.orderPublicId",
                            "providerEventId": "$item.providerEventId",
                            "normalizedStatus": "$item.normalizedStatus",
                            "occurredAt": "$item.occurredAt",
                            "providerReference": "$item.providerReference",
                            "recipientHandoffAt": "$item.recipientHandoffAt",
                            "carrierAcceptedAt": "$item.carrierAcceptedAt"
                        }
                    }
                },
                {
                    "id": "acknowledge",
                    "call": {
                        "source": "{{dependencies.delivery.sourceId}}",
                        "endpoint": "acknowledgeShipmentEvent",
                        "body": {
                            "eventId": "$item.eventId",
                            "claimToken": "$item.claimToken"
                        }
                    }
                }
            ],
            "yield": "$steps.record",
            "onError": [
                {
                    "id": "failOrderProjection",
                    "call": {
                        "source": "{{dependencies.delivery.sourceId}}",
                        "endpoint": "failShipmentEventProjection",
                        "body": {
                            "eventId": "$item.eventId",
                            "claimToken": "$item.claimToken",
                            "error": "Commerce order fulfillment projection failed"
                        }
                    }
                }
            ],
            "errorYield": {
                "eventId": "$item.eventId",
                "providerEventId": "$item.providerEventId",
                "projectionFailed": true,
                "failure": "$steps.failOrderProjection"
            }
        }
    },
    {
        "id": "commerceClaimReturnEvents",
        "forEach": {
            "items": "$steps.deliveryBatch.claimReturnEvents",
            "max": 8,
            "continueOnError": true,
            "steps": [
                {
                    "id": "recordClaimReturn",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "recordClaimReturnDelivery",
                        "body": {
                            "claimId": "$item.claimId",
                            "providerEventId": "$item.providerEventId",
                            "providerReference": "$item.providerReference",
                            "normalizedStatus": "$item.normalizedStatus",
                            "occurredAt": "$item.occurredAt",
                            "providerEvidence": "$item.providerEvidence"
                        }
                    }
                },
                {
                    "id": "acknowledgeClaimReturn",
                    "call": {
                        "source": "{{dependencies.delivery.sourceId}}",
                        "endpoint": "acknowledgeShipmentEvent",
                        "body": {
                            "eventId": "$item.eventId",
                            "claimToken": "$item.claimToken"
                        }
                    }
                }
            ],
            "yield": "$steps.recordClaimReturn",
            "onError": [
                {
                    "id": "failClaimReturnProjection",
                    "call": {
                        "source": "{{dependencies.delivery.sourceId}}",
                        "endpoint": "failShipmentEventProjection",
                        "body": {
                            "eventId": "$item.eventId",
                            "claimToken": "$item.claimToken",
                            "error": "Commerce claim return projection failed"
                        }
                    }
                }
            ],
            "errorYield": {
                "eventId": "$item.eventId",
                "providerEventId": "$item.providerEventId",
                "projectionFailed": true,
                "failure": "$steps.failClaimReturnProjection"
            }
        }
    }
]

{
    "id": "reconcileMondialRelayShipmentOperations",
    "method": "POST",
    "access": {
        "mode": "system"
    },
    "meta": {
        "name": "Reconcile Mondial Relay shipment operations",
        "description": "Recover durable shipment creation and cancellation sagas without holding database locks across provider calls."
    },
    "input": {
        "body": {
            "type": "object",
            "properties": {
                "runKey": {
                    "type": "string"
                },
                "limit": {
                    "type": "number"
                }
            },
            "required": [
                "runKey",
                "limit"
            ]
        }
    },
    "output": [
        {
            "status": "200",
            "body": {
                "type": "object"
            }
        }
    ],
    "steps": {
        "$include": "steps.json"
    },
    "return": {
        "status": 200,
        "body": {
            "creations": "$steps.creations",
            "cancellations": "$steps.cancellations"
        }
    }
}

[
    {
        "id": "cancellations",
        "forEach": {
            "items": "$steps.cancellationClaims.items",
            "max": 5,
            "continueOnError": true,
            "steps": [
                {
                    "id": "deliveryCancellation",
                    "call": {
                        "source": "{{dependencies.delivery.sourceId}}",
                        "endpoint": "cancelShipmentReservation",
                        "body": {
                            "externalOrderId": "$item.orderPublicId",
                            "trackingUntil": "$item.trackingUntil"
                        }
                    }
                },
                {
                    "id": "completeCancellation",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "completeOrderShipmentCancellation",
                        "body": {
                            "operationId": "$item.operationId",
                            "claimToken": "$item.claimToken",
                            "providerStatus": "$steps.deliveryCancellation.status",
                            "providerReference": "$steps.deliveryCancellation.expeditionNumber",
                            "providerSnapshot": "$steps.deliveryCancellation"
                        }
                    }
                }
            ],
            "yield": "$steps.completeCancellation",
            "onError": [
                {
                    "id": "failCancellation",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "failOrderShipmentCancellation",
                        "body": {
                            "operationId": "$item.operationId",
                            "claimToken": "$item.claimToken",
                            "error": "Mondial Relay shipment cancellation reconciliation failed"
                        }
                    }
                }
            ],
            "errorYield": {
                "operationId": "$item.operationId",
                "failed": true,
                "failure": "$steps.failCancellation"
            }
        }
    }
]

[
    {
        "id": "creationClaims",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "claimPendingShipmentCreations",
            "body": {
                "runKey": "$input.body.runKey",
                "limit": "$input.body.limit"
            }
        }
    },
    {
        "id": "creations",
        "forEach": {
            "items": "$steps.creationClaims.items",
            "max": 5,
            "continueOnError": true,
            "steps": [
                {
                    "id": "quote",
                    "call": {
                        "source": "{{dependencies.delivery.sourceId}}",
                        "endpoint": "resolveDeliveryQuote",
                        "body": {
                            "quoteId": "$item.deliveryQuoteId",
                            "externalOrderId": "$item.orderPublicId",
                            "selectedForCmsUserId": "$item.buyerCmsUserId",
                            "merchandiseSubtotalMinorAmount": "$item.merchandiseSubtotalMinorAmount",
                            "currency": "$item.currency",
                            "purpose": "fulfillment"
                        }
                    }
                },
                {
                    "id": "shipment",
                    "call": {
                        "source": "{{dependencies.delivery.sourceId}}",
                        "endpoint": "createShipment",
                        "body": {
                            "externalOrderId": "$item.orderPublicId",
                            "sellerCmsUserId": "$item.sellerId",
                            "deliveryQuoteId": "$steps.quote.quoteId",
                            "quoteExternalOrderId": "$steps.quote.externalOrderId",
                            "quotePurpose": "fulfillment",
                            "selectedForCmsUserId": "$item.buyerCmsUserId",
                            "senderName": "$steps.quote.sellerFulfillmentSnapshot.name",
                            "senderFirstName": "$steps.quote.sellerFulfillmentSnapshot.firstName",
                            "senderLastName": "$steps.quote.sellerFulfillmentSnapshot.lastName",
                            "senderEmail": "$steps.quote.sellerFulfillmentSnapshot.email",
                            "senderPhone": "$steps.quote.sellerFulfillmentSnapshot.phone",
                            "senderAddressLine1": "$steps.quote.sellerFulfillmentSnapshot.addressLine1",
                            "senderAddressLine2": "$steps.quote.sellerFulfillmentSnapshot.addressLine2",
                            "senderAddressLine3": "$steps.quote.sellerFulfillmentSnapshot.addressLine3",
                            "senderPostalCode": "$steps.quote.sellerFulfillmentSnapshot.postalCode",
                            "senderCity": "$steps.quote.sellerFulfillmentSnapshot.city",
                            "senderCountry": "$steps.quote.sellerFulfillmentSnapshot.country",
                            "recipientName": "$steps.quote.recipientSnapshot.name",
                            "recipientFirstName": "$steps.quote.recipientSnapshot.firstName",
                            "recipientLastName": "$steps.quote.recipientSnapshot.lastName",
                            "recipientEmail": "$steps.quote.recipientSnapshot.email",
                            "recipientPhone": "$steps.quote.recipientSnapshot.phone",
                            "recipientAddressLine1": "$steps.quote.recipientSnapshot.addressLine1",
                            "recipientAddressLine2": "$steps.quote.recipientSnapshot.addressLine2",
                            "recipientAddressLine3": "$steps.quote.recipientSnapshot.addressLine3",
                            "recipientPostalCode": "$steps.quote.recipientSnapshot.postalCode",
                            "recipientCity": "$steps.quote.recipientSnapshot.city",
                            "recipientCountry": "$steps.quote.recipientSnapshot.country",
                            "deliveryRelayLocation": "$steps.quote.relayLocation",
                            "weightGrams": "$steps.quote.weightGrams",
                            "packageCount": 1,
                            "declaredValueMinorAmount": "$item.merchandiseSubtotalMinorAmount",
                            "declaredCurrency": "EUR",
                            "metadata": {
                                "commerceOrderId": "$item.orderPublicId",
                                "financialTermsHash": "$item.financialTermsHash",
                                "deliveryQuoteId": "$item.deliveryQuoteId",
                                "declaredValueMinorAmount": "$item.merchandiseSubtotalMinorAmount",
                                "declaredCurrency": "EUR"
                            }
                        }
                    }
                },
                {
                    "id": "complete",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "completeOrderShipmentCreation",
                        "body": {
                            "operationId": "$item.operationId",
                            "claimToken": "$item.claimToken",
                            "providerReference": "$steps.shipment.expeditionNumber",
                            "providerShipmentId": "$steps.shipment.id",
                            "providerSnapshot": {
                                "status": "$steps.shipment.status",
                                "createdAt": "$steps.shipment.createdAt"
                            }
                        }
                    }
                }
            ],
            "yield": "$steps.complete",
            "onError": [
                {
                    "id": "failCreation",
                    "call": {
                        "source": "{{dependencies.commerce.sourceId}}",
                        "endpoint": "failOrderShipmentCreation",
                        "body": {
                            "operationId": "$item.operationId",
                            "claimToken": "$item.claimToken",
                            "error": "Mondial Relay shipment creation reconciliation failed"
                        }
                    }
                }
            ],
            "errorYield": {
                "operationId": "$item.operationId",
                "failed": true,
                "failure": "$steps.failCreation"
            }
        }
    },
    {
        "id": "cancellationClaims",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "claimPendingShipmentCancellations",
            "body": {
                "runKey": "$input.body.runKey",
                "limit": "$input.body.limit"
            }
        }
    }
]

{
    "type": "function",
    "function": {
        "id": "recoverMondialRelayShipmentCreation",
        "method": "POST",
        "access": {
            "mode": "admin"
        },
        "meta": {
            "name": "Recover Mondial Relay shipment creation",
            "description": "Attach a verified provider shipment and complete the matching Commerce creation operation with an audited operator reason."
        },
        "input": {
            "body": {
                "type": "object",
                "properties": {
                    "shipmentId": {
                        "type": "string"
                    },
                    "orderPublicId": {
                        "type": "string"
                    },
                    "expeditionNumber": {
                        "type": "string"
                    },
                    "labelUrl": {
                        "type": "string"
                    },
                    "reason": {
                        "type": "string"
                    }
                },
                "required": [
                    "shipmentId",
                    "orderPublicId",
                    "expeditionNumber",
                    "reason"
                ]
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "assert": {
                    "condition": {
                        "equals": [
                            "$ctx.user.role",
                            "admin"
                        ]
                    },
                    "failure": {
                        "status": 403,
                        "error": "Shipment recovery requires an admin"
                    }
                }
            },
            {
                "id": "deliveryRecovery",
                "call": {
                    "source": "{{dependencies.delivery.sourceId}}",
                    "endpoint": "recoverUnknownShipment",
                    "body": {
                        "shipmentId": "$input.body.shipmentId",
                        "externalOrderId": "$input.body.orderPublicId",
                        "expeditionNumber": "$input.body.expeditionNumber",
                        "labelUrl": "$input.body.labelUrl",
                        "reason": "$input.body.reason"
                    }
                }
            },
            {
                "id": "commerceRecovery",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "recoverOrderShipmentCreation",
                    "body": {
                        "orderPublicId": "$input.body.orderPublicId",
                        "providerReference": "$steps.deliveryRecovery.expeditionNumber",
                        "providerShipmentId": "$steps.deliveryRecovery.id",
                        "reason": "$input.body.reason",
                        "providerSnapshot": "$steps.deliveryRecovery"
                    }
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "shipment": "$steps.deliveryRecovery",
                "fulfillment": "$steps.commerceRecovery"
            }
        }
    }
}

definitions/artifacts/functions/shipment.content:
{
    "type": "function",
    "function": {
        "id": "cancelMondialRelayShipment",
        "method": "POST",
        "access": {
            "mode": "system"
        },
        "meta": {
            "name": "Cancel Mondial Relay shipment",
            "description": "Apply an already-authorized pre-carrier cancellation against the same shipment state used by scans."
        },
        "input": {
            "body": {
                "type": "object",
                "properties": {
                    "orderPublicId": {
                        "type": "string"
                    },
                    "providerEventId": {
                        "type": "string"
                    },
                    "occurredAt": {
                        "type": "string"
                    },
                    "trackingUntil": {
                        "type": "string"
                    }
                },
                "required": [
                    "orderPublicId",
                    "providerEventId",
                    "occurredAt",
                    "trackingUntil"
                ]
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "id": "shipment",
                "call": {
                    "source": "{{dependencies.delivery.sourceId}}",
                    "endpoint": "cancelShipmentReservation",
                    "body": {
                        "externalOrderId": "$input.body.orderPublicId",
                        "trackingUntil": "$input.body.trackingUntil"
                    }
                }
            },
            {
                "id": "commerceFulfillment",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "recordOrderFulfillment",
                    "body": {
                        "orderPublicId": "$input.body.orderPublicId",
                        "providerEventId": "$input.body.providerEventId",
                        "normalizedStatus": "cancelled",
                        "occurredAt": "$input.body.occurredAt",
                        "providerReference": "$steps.shipment.expeditionNumber"
                    }
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "shipment": "$steps.shipment",
                "fulfillment": "$steps.commerceFulfillment"
            }
        }
    }
}

{
    "id": "createShipmentForMySale",
    "method": "POST",
    "access": {
        "mode": "auth"
    },
    "meta": {
        "name": "Create shipment for my sale",
        "description": "Create one idempotent 24R shipment after Commerce authorizes the seller fulfillment."
    },
    "input": {
        "body": {
            "type": "object",
            "properties": {
                "orderId": {
                    "type": "string"
                }
            },
            "required": [
                "orderId"
            ]
        }
    },
    "output": [
        {
            "status": "200",
            "body": {
                "type": "object"
            }
        }
    ],
    "steps": {
        "$include": "steps/root.json"
    },
    "return": {
        "status": 200,
        "body": {
            "orderId": "$steps.sale.id",
            "orderPublicId": "$steps.sale.publicId",
            "shipment": "$steps.shipment",
            "fulfillment": "$steps.commerceFulfillment"
        }
    }
}

[
    {
        "id": "sale",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "getOrderShipmentCreationSellerContext",
            "params": {
                "orderId": "$input.body.orderId"
            }
        }
    },
    {
        "assert": {
            "condition": {
                "equals": [
                    "$steps.sale.sellerId",
                    "$ctx.user.id"
                ]
            },
            "failure": {
                "status": 403,
                "error": "Fulfillment authorization belongs to another seller"
            }
        }
    },
    {
        "assert": {
            "condition": {
                "equals": [
                    "$steps.sale.allowed",
                    true
                ]
            },
            "failure": {
                "status": 409,
                "error": "Commerce has not authorized shipment creation"
            }
        }
    },
    {
        "id": "authorization",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "reserveOrderShipmentCreation",
            "body": {
                "orderPublicId": "$steps.sale.publicId",
                "workerId": {
                    "$concat": [
                        "seller-request:",
                        "$ctx.user.id"
                    ]
                }
            }
        }
    },
    {
        "assert": {
            "condition": {
                "equals": [
                    "$steps.authorization.sellerId",
                    "$ctx.user.id"
                ]
            },
            "failure": {
                "status": 403,
                "error": "Shipment creation reservation belongs to another seller"
            }
        }
    },
    {
        "id": "quote",
        "call": {
            "source": "{{dependencies.delivery.sourceId}}",
            "endpoint": "resolveDeliveryQuote",
            "body": {
                "quoteId": "$steps.authorization.deliveryQuoteId",
                "externalOrderId": "$steps.sale.publicId",
                "selectedForCmsUserId": "$steps.authorization.buyerCmsUserId",
                "merchandiseSubtotalMinorAmount": "$steps.authorization.merchandiseSubtotalMinorAmount",
                "currency": "$steps.authorization.currency",
                "purpose": "fulfillment"
            }
        }
    },
    {
        "$include": "shipment.json"
    },
    {
        "id": "commerceFulfillment",
        "call": {
            "source": "{{dependencies.commerce.sourceId}}",
            "endpoint": "completeOrderShipmentCreation",
            "body": {
                "operationId": "$steps.authorization.operationId",
                "claimToken": "$steps.authorization.claimToken",
                "providerReference": "$steps.shipment.expeditionNumber",
                "providerShipmentId": "$steps.shipment.id",
                "providerSnapshot": {
                    "status": "$steps.shipment.status",
                    "createdAt": "$steps.shipment.createdAt"
                }
            }
        }
    }
]

{
    "type": "function",
    "function": {
        "id": "declareShipmentHandoffForMySale",
        "method": "POST",
        "access": {
            "mode": "auth"
        },
        "meta": {
            "name": "Declare shipment handoff for my sale",
            "description": "Record the seller assertion separately from the first trusted carrier scan."
        },
        "input": {
            "body": {
                "type": "object",
                "properties": {
                    "orderId": {
                        "type": "string"
                    }
                },
                "required": [
                    "orderId"
                ]
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "id": "sale",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "getOrderFulfillmentSellerContext",
                    "params": {
                        "orderId": "$input.body.orderId"
                    }
                }
            },
            {
                "id": "handoff",
                "call": {
                    "source": "{{dependencies.delivery.sourceId}}",
                    "endpoint": "declareSellerHandoff",
                    "body": {
                        "externalOrderId": "$steps.sale.publicId"
                    }
                }
            },
            {
                "id": "commerceFulfillment",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "recordOrderFulfillment",
                    "body": {
                        "orderPublicId": "$steps.sale.publicId",
                        "providerEventId": {
                            "$concat": [
                                "mondial-relay|",
                                "$steps.handoff.expeditionNumber",
                                "|seller_handoff|",
                                "$steps.handoff.sellerHandoffDeclaredAt"
                            ]
                        },
                        "normalizedStatus": "seller_handoff_declared",
                        "occurredAt": "$steps.handoff.sellerHandoffDeclaredAt",
                        "providerReference": "$steps.handoff.expeditionNumber",
                        "sellerHandoffDeclaredAt": "$steps.handoff.sellerHandoffDeclaredAt"
                    }
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "shipment": "$steps.handoff",
                "fulfillment": "$steps.commerceFulfillment"
            }
        }
    }
}

{
    "type": "function",
    "function": {
        "id": "getShipmentForMySale",
        "method": "GET",
        "access": {
            "mode": "auth"
        },
        "meta": {
            "name": "Get shipment for my sale",
            "description": "Return a sanitized shipment projection after Commerce resolves seller ownership."
        },
        "input": {
            "params": {
                "orderId": {
                    "type": "string"
                }
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "id": "sale",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "getOrderFulfillmentSellerContext",
                    "params": {
                        "orderId": "$input.params.orderId"
                    }
                }
            },
            {
                "id": "shipments",
                "call": {
                    "source": "{{dependencies.delivery.sourceId}}",
                    "endpoint": "shipmentForExternalOrder",
                    "params": {
                        "externalOrderId": "$steps.sale.publicId"
                    }
                }
            },
            {
                "id": "details",
                "forEach": {
                    "items": "$steps.shipments.items",
                    "max": 1,
                    "steps": [
                        {
                            "assert": {
                                "condition": {
                                    "exists": "$item.id"
                                }
                            }
                        }
                    ],
                    "yield": {
                        "id": "$item.id",
                        "expeditionNumber": "$item.expeditionNumber",
                        "status": "$item.status",
                        "trackingUrl": "$item.trackingUrl",
                        "deliveryRelayLocation": "$item.deliveryRelayLocation",
                        "latestEventLabel": "$item.latestEventLabel",
                        "latestEventAt": "$item.latestEventAt",
                        "carrierAcceptedAt": "$item.carrierAcceptedAt",
                        "sellerHandoffDeclaredAt": "$item.sellerHandoffDeclaredAt",
                        "recipientHandoffAt": "$item.recipientHandoffAt",
                        "createdAt": "$item.createdAt",
                        "events": "$item.events"
                    }
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "orderId": "$steps.sale.id",
                "orderPublicId": "$steps.sale.publicId",
                "orderNumber": "$steps.sale.orderNumber",
                "shipments": "$steps.details"
            }
        }
    }
}

{
    "type": "function",
    "function": {
        "id": "getShipmentForOrder",
        "method": "GET",
        "access": {
            "mode": "auth"
        },
        "meta": {
            "name": "Get shipment for order",
            "description": "Return an allowlisted tracking projection after Commerce verifies buyer ownership."
        },
        "input": {
            "params": {
                "orderId": {
                    "type": "string"
                }
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "id": "order",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "getOrderFulfillmentBuyerContext",
                    "params": {
                        "orderId": "$input.params.orderId"
                    }
                }
            },
            {
                "assert": {
                    "condition": {
                        "equals": [
                            "$steps.order.buyerCmsUserId",
                            "$ctx.user.id"
                        ]
                    },
                    "failure": {
                        "status": 403,
                        "error": "Order does not belong to the current buyer"
                    }
                }
            },
            {
                "id": "shipments",
                "call": {
                    "source": "{{dependencies.delivery.sourceId}}",
                    "endpoint": "shipmentForExternalOrder",
                    "params": {
                        "externalOrderId": "$steps.order.publicId"
                    }
                }
            },
            {
                "id": "tracking",
                "forEach": {
                    "items": "$steps.shipments.items",
                    "max": 1,
                    "steps": [
                        {
                            "assert": {
                                "condition": {
                                    "exists": "$item.id"
                                }
                            }
                        }
                    ],
                    "yield": {
                        "id": "$item.id",
                        "expeditionNumber": "$item.expeditionNumber",
                        "status": "$item.status",
                        "trackingUrl": "$item.trackingUrl",
                        "deliveryRelayLocation": "$item.deliveryRelayLocation",
                        "latestEventLabel": "$item.latestEventLabel",
                        "latestEventAt": "$item.latestEventAt",
                        "carrierAcceptedAt": "$item.carrierAcceptedAt",
                        "recipientHandoffAt": "$item.recipientHandoffAt",
                        "createdAt": "$item.createdAt",
                        "events": "$item.events"
                    }
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "orderId": "$steps.order.id",
                "orderPublicId": "$steps.order.publicId",
                "shipments": "$steps.tracking"
            }
        }
    }
}

{
    "type": "function",
    "function": {
        "id": "requestShipmentLabelForMySale",
        "method": "POST",
        "access": {
            "mode": "auth"
        },
        "meta": {
            "name": "Request shipment label for my sale",
            "description": "Issue a short-lived seller-bound label capability without exposing the provider URL."
        },
        "input": {
            "body": {
                "type": "object",
                "properties": {
                    "orderId": {
                        "type": "string"
                    }
                },
                "required": [
                    "orderId"
                ]
            }
        },
        "output": [
            {
                "status": "200",
                "body": {
                    "type": "object"
                }
            }
        ],
        "steps": [
            {
                "id": "labelContext",
                "call": {
                    "source": "{{dependencies.commerce.sourceId}}",
                    "endpoint": "getOrderLabelSellerContext",
                    "params": {
                        "orderId": "$input.body.orderId"
                    }
                }
            },
            {
                "assert": {
                    "condition": {
                        "all": [
                            {
                                "equals": [
                                    "$steps.labelContext.allowed",
                                    true
                                ]
                            },
                            {
                                "equals": [
                                    "$steps.labelContext.sellerCmsUserId",
                                    "$ctx.user.id"
                                ]
                            }
                        ]
                    },
                    "failure": {
                        "status": 409,
                        "error": "Commerce has not authorized label access"
                    }
                }
            },
            {
                "id": "capability",
                "call": {
                    "source": "{{dependencies.delivery.sourceId}}",
                    "endpoint": "issueLabelAccess",
                    "body": {
                        "externalOrderId": "$steps.labelContext.publicId",
                        "sellerCmsUserId": "$ctx.user.id"
                    }
                }
            }
        ],
        "return": {
            "status": 200,
            "body": {
                "labelUrl": {
                    "$concat": [
                        "/.cms/sources/{{dependencies.delivery.sourceId}}/label?token=",
                        "$steps.capability.token"
                    ]
                },
                "expiresAt": "$steps.capability.expiresAt"
            }
        }
    }
}
